def shipping_cost(weight_kg, zone, express):
    # Works, but every rule is another branch.
    if weight_kg <= 0:
        return -1
    if weight_kg > 30:
        return -1
    if zone == "domestic":
        if express:
            return 1000 + 100 * weight_kg
        else:
            return 500 + 100 * weight_kg
    elif zone == "europe":
        if express:
            return 1800 + 250 * weight_kg
        else:
            return 900 + 250 * weight_kg
    elif zone == "world":
        if express:
            return 3000 + 400 * weight_kg
        else:
            return 1500 + 400 * weight_kg
    else:
        return -1
